from collections import defaultdict


class QuotaExceededError(Exception):
    """Raised when an upload would exceed the monthly quota limit."""
    pass


class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # Tracks current size per file per month: month -> {file_name: size_bytes}
        self._files: dict[str, dict[str, int]] = defaultdict(dict)
        # Tracks total quota used (consumed) per month: month -> int
        self._monthly_used: dict[str, int] = defaultdict(int)

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like "2026-01"."""
        if size_bytes <= 0:
            raise ValueError("File size must be greater than 0.")

        current_files = self._files[month]
        current_used = self._monthly_used[month]

        if name in current_files:
            existing_size = current_files[name]
            # Additional bytes needed if re-uploading with a larger size
            additional_bytes = max(0, size_bytes - existing_size)
            if current_used + additional_bytes > self.limit_bytes:
                raise QuotaExceededError(
                    f"Upload exceeds quota for {month}. Limit: {self.limit_bytes} bytes, "
                    f"Requested: {current_used + additional_bytes} bytes."
                )
            self._monthly_used[month] += additional_bytes
            current_files[name] = max(existing_size, size_bytes)
        else:
            if current_used + size_bytes > self.limit_bytes:
                raise QuotaExceededError(
                    f"Upload exceeds quota for {month}. Limit: {self.limit_bytes} bytes, "
                    f"Requested: {current_used + size_bytes} bytes."
                )
            self._monthly_used[month] += size_bytes
            current_files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        """Deleting a file does not recover quota for the month."""
        self._files[month].pop(name, None)

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return self._monthly_used[month]
